/*
 * With the Nova Digital (Tuya) coordinator, the responses generated by the
 * stack for these requests never reached the coordinator, so the application
 * answers them itself. The format is standard Zigbee and also works with
 * Zigbee2MQTT/ZHA.
 */

#include "zb_responses.h"

#include <stdbool.h>
#include <string.h>

#include "all_device_types_app.h"
#include "esp_log.h"
#include "network.h"
#include "relay.h"

static const char *TAG = "zb_responses";

#define ARRAY_LEN(a)                        (sizeof(a) / sizeof((a)[0]))

/* ZDO */
#define ZDO_PROFILE_ID                      0x0000
#define ZDO_NWK_ADDR_REQ                    0x0000
#define ZDO_IEEE_ADDR_REQ                   0x0001
#define ZDO_SIMPLE_DESC_REQ                 0x0004
#define ZDO_ACTIVE_EP_REQ                   0x0005
#define ZDO_MATCH_DESC_REQ                  0x0006
#define ZDO_RESPONSE_FLAG                   0x8000
#define ZDO_STATUS_SUCCESS                  0x00
#define ZDO_STATUS_NOT_ACTIVE               0x83

/* Home Automation */
#define HA_PROFILE_ID                       0x0104
#define HA_WILDCARD_PROFILE_ID              0xFFFF
#define HA_ON_OFF_LIGHT_DEVICE_ID           0x0100

/* ZCL */
#define ZCL_FRAME_TYPE_MASK                 0x03
#define ZCL_FRAME_TYPE_CLUSTER_SPECIFIC     0x01
#define ZCL_FC_SERVER_TO_CLIENT_NO_DEF_RSP  0x18
#define ZCL_CMD_READ_ATTRIBUTES             0x00
#define ZCL_CMD_READ_ATTRIBUTES_RSP         0x01
#define ZCL_CMD_WRITE_ATTRIBUTES            0x02
#define ZCL_CMD_DEFAULT_RSP                 0x0b
#define ZCL_STATUS_SUCCESS                  0x00
#define ZCL_STATUS_UNSUPPORTED_ATTRIBUTE    0x86
#define ZCL_TYPE_UINT8                      0x20
#define ZCL_TYPE_ENUM8                      0x30
#define ZCL_TYPE_CHAR_STRING                0x42
#define ZCL_MAX_ATTR_RECORD_LEN             21   /* id(2) status(1) type(1) string(17) */

#define COORDINATOR_SHORT_ADDR              0x0000
#define INVALID_SHORT_ADDR                  0xFFFF

/* Server clusters of the On/Off Light endpoint (must match the created endpoint) */
static const uint16_t s_server_clusters[] = {
    0x0000, /* Basic */
    0x0003, /* Identify */
    0x0004, /* Groups */
    0x0005, /* Scenes */
    0x0006, /* On/Off */
};

/* -------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* -------------------------------------------------------------------------- */

static uint16_t put_u16(uint8_t *buf, uint16_t value)
{
    buf[0] = value & 0xff;
    buf[1] = value >> 8;
    return 2;
}

static uint16_t put_u64(uint8_t *buf, uint64_t value)
{
    for (int i = 0; i < 8; i++) {
        buf[i] = (value >> (8 * i)) & 0xff;
    }
    return 8;
}

static uint16_t get_u16(const uint8_t *buf)
{
    return buf[0] | (buf[1] << 8);
}

static uint64_t get_u64(const uint8_t *buf)
{
    uint64_t value = 0;

    for (int i = 0; i < 8; i++) {
        value |= (uint64_t)buf[i] << (8 * i);
    }
    return value;
}

static uint16_t short_addr_of(const ezb_address_t *addr, uint16_t fallback)
{
    return addr->addr_mode == EZB_ADDR_MODE_SHORT ? addr->u.short_addr : fallback;
}

static bool is_server_cluster(uint16_t cluster_id)
{
    for (size_t i = 0; i < ARRAY_LEN(s_server_clusters); i++) {
        if (s_server_clusters[i] == cluster_id) {
            return true;
        }
    }
    return false;
}

static void aps_send(uint16_t dst_short,
                     uint16_t profile_id,
                     uint16_t cluster_id,
                     uint8_t src_ep,
                     uint8_t dst_ep,
                     uint8_t *asdu,
                     uint16_t asdu_length)
{
    ezb_apsde_data_req_t req = {
        .dst_address = {
            .addr_mode    = EZB_ADDR_MODE_SHORT,
            .u.short_addr = dst_short,
        },
        .src_endpoint = src_ep,
        .dst_endpoint = dst_ep,
        .cluster_id   = cluster_id,
        .profile_id   = profile_id,
        /*
         * No APS ACK while joining: retransmissions before the Trust Center
         * link key exchange made the join fail (BDB status 0x0a).
         */
        .tx_options   = network_is_joined() ? EZB_APSDE_TX_OPT_ACK_TX : 0,
        .asdu_length  = asdu_length,
        .asdu         = asdu,
    };

    if (ezb_apsde_data_request(&req) != EZB_ERR_NONE) {
        ESP_LOGW(TAG, "Failed to send cluster 0x%04x to 0x%04x", cluster_id, dst_short);
    }
}

/* -------------------------------------------------------------------------- */
/* ZDO responses                                                              */
/* -------------------------------------------------------------------------- */

static void zdo_reply_nwk_addr(uint16_t dst, uint8_t tsn, uint64_t ieee, uint16_t my_short)
{
    static uint8_t rsp[12];
    uint16_t n = 0;

    rsp[n++] = tsn;
    rsp[n++] = ZDO_STATUS_SUCCESS;
    n += put_u64(&rsp[n], ieee);
    n += put_u16(&rsp[n], my_short);

    aps_send(dst, ZDO_PROFILE_ID, ZDO_NWK_ADDR_REQ | ZDO_RESPONSE_FLAG, 0, 0, rsp, n);
}

static void zdo_reply_ieee_addr(uint16_t dst, uint8_t tsn, uint16_t my_short)
{
    static uint8_t rsp[12];
    ezb_extaddr_t ieee;
    uint16_t n = 0;

    ezb_nwk_get_extended_address(&ieee);

    rsp[n++] = tsn;
    rsp[n++] = ZDO_STATUS_SUCCESS;
    n += put_u64(&rsp[n], ieee.u64);
    n += put_u16(&rsp[n], my_short);

    aps_send(dst, ZDO_PROFILE_ID, ZDO_IEEE_ADDR_REQ | ZDO_RESPONSE_FLAG, 0, 0, rsp, n);
}

static void zdo_reply_active_ep(uint16_t dst, uint8_t tsn, uint16_t my_short)
{
    static uint8_t rsp[6];
    uint16_t n = 0;

    rsp[n++] = tsn;
    rsp[n++] = ZDO_STATUS_SUCCESS;
    n += put_u16(&rsp[n], my_short);
    rsp[n++] = 1; /* endpoint count */
    rsp[n++] = ZIGBEE_ENDPOINT;

    aps_send(dst, ZDO_PROFILE_ID, ZDO_ACTIVE_EP_REQ | ZDO_RESPONSE_FLAG, 0, 0, rsp, n);
}

static uint16_t put_simple_descriptor(uint8_t *buf)
{
    uint16_t n = 0;

    buf[n++] = ZIGBEE_ENDPOINT;
    n += put_u16(&buf[n], HA_PROFILE_ID);
    n += put_u16(&buf[n], HA_ON_OFF_LIGHT_DEVICE_ID);
    buf[n++] = 0x01; /* device version */

    buf[n++] = ARRAY_LEN(s_server_clusters);
    for (size_t i = 0; i < ARRAY_LEN(s_server_clusters); i++) {
        n += put_u16(&buf[n], s_server_clusters[i]);
    }

    buf[n++] = 0; /* no client clusters */
    return n;
}

static void zdo_reply_simple_desc(uint16_t dst, uint8_t tsn, uint16_t my_short, uint8_t ep)
{
    static uint8_t rsp[32];
    uint16_t n = 0;

    rsp[n++] = tsn;
    rsp[n++] = ep == ZIGBEE_ENDPOINT ? ZDO_STATUS_SUCCESS : ZDO_STATUS_NOT_ACTIVE;
    n += put_u16(&rsp[n], my_short);

    if (ep == ZIGBEE_ENDPOINT) {
        uint16_t len_pos = n++;

        n += put_simple_descriptor(&rsp[n]);
        rsp[len_pos] = n - len_pos - 1;
    } else {
        rsp[n++] = 0; /* descriptor length */
    }

    aps_send(dst, ZDO_PROFILE_ID, ZDO_SIMPLE_DESC_REQ | ZDO_RESPONSE_FLAG, 0, 0, rsp, n);
}

/* Match_Desc_req: TSN(1) NWK(2) Profile(2) InCount(1) InClusters(2n) OutCount(1) ... */
static bool match_desc_matches(const uint8_t *req, uint16_t len)
{
    if (len < 6) {
        return false;
    }

    uint16_t profile = get_u16(&req[3]);

    if (profile != HA_PROFILE_ID && profile != HA_WILDCARD_PROFILE_ID) {
        return false;
    }

    /* Only input clusters can match: the endpoint has no client clusters */
    uint8_t in_count = req[5];

    for (uint16_t i = 0, pos = 6; i < in_count && pos + 1 < len; i++, pos += 2) {
        if (is_server_cluster(get_u16(&req[pos]))) {
            return true;
        }
    }

    return false;
}

static void zdo_reply_match_desc(uint16_t dst, const uint8_t *req, uint16_t len, uint16_t my_short)
{
    static uint8_t rsp[6];
    uint16_t n = 0;

    rsp[n++] = req[0];
    rsp[n++] = ZDO_STATUS_SUCCESS;
    n += put_u16(&rsp[n], my_short);

    if (match_desc_matches(req, len)) {
        rsp[n++] = 1;
        rsp[n++] = ZIGBEE_ENDPOINT;
    } else {
        rsp[n++] = 0;
    }

    aps_send(dst, ZDO_PROFILE_ID, ZDO_MATCH_DESC_REQ | ZDO_RESPONSE_FLAG, 0, 0, rsp, n);
}

/* Returns true when the request was answered (the stack must drop it) */
static bool handle_zdo_request(const ezb_apsde_data_ind_t *ind, uint16_t src)
{
    const uint8_t *req = ind->asdu;
    uint16_t len = ind->asdu_length;
    uint16_t my_short = ezb_nwk_get_short_address();

    if (req == NULL || len < 3) {
        return false;
    }

    /* NWK_Addr_req: TSN(1) IEEE(8) RequestType(1) StartIndex(1) */
    if (ind->cluster_id == ZDO_NWK_ADDR_REQ) {
        ezb_extaddr_t ieee;

        ezb_nwk_get_extended_address(&ieee);

        if (len < 9 || get_u64(&req[1]) != ieee.u64) {
            return false;
        }

        zdo_reply_nwk_addr(src, req[0], ieee.u64, my_short);
        return true;
    }

    /* Other requests: TSN(1) NWKAddrOfInterest(2) ... */
    if (get_u16(&req[1]) != my_short) {
        return false;
    }

    switch (ind->cluster_id) {
    case ZDO_IEEE_ADDR_REQ:
        zdo_reply_ieee_addr(src, req[0], my_short);
        return true;

    case ZDO_ACTIVE_EP_REQ:
        zdo_reply_active_ep(src, req[0], my_short);
        return true;

    case ZDO_SIMPLE_DESC_REQ:
        if (len < 4) {
            return false;
        }
        zdo_reply_simple_desc(src, req[0], my_short, req[3]);
        return true;

    case ZDO_MATCH_DESC_REQ:
        zdo_reply_match_desc(src, req, len, my_short);
        return true;

    default:
        return false;
    }
}

/* -------------------------------------------------------------------------- */
/* ZCL                                                                        */
/* -------------------------------------------------------------------------- */

static uint16_t put_u8_attr(uint8_t *buf, uint8_t type, uint8_t value)
{
    buf[0] = ZCL_STATUS_SUCCESS;
    buf[1] = type;
    buf[2] = value;
    return 3;
}

/* zcl_str is a ZCL string: first byte is the length */
static uint16_t put_string_attr(uint8_t *buf, const char *zcl_str)
{
    uint16_t len = (uint8_t)zcl_str[0] + 1;

    buf[0] = ZCL_STATUS_SUCCESS;
    buf[1] = ZCL_TYPE_CHAR_STRING;
    memcpy(&buf[2], zcl_str, len);
    return 2 + len;
}

/* One Read Attributes Response record for the Basic cluster */
static uint16_t put_basic_attr_record(uint8_t *buf, uint16_t attr_id)
{
    uint16_t n = put_u16(buf, attr_id);

    switch (attr_id) {
    case EZB_ZCL_ATTR_BASIC_ZCL_VERSION_ID:
        return n + put_u8_attr(&buf[n], ZCL_TYPE_UINT8, EZB_ZCL_BASIC_ZCL_VERSION_DEFAULT_VALUE);
    case EZB_ZCL_ATTR_BASIC_APPLICATION_VERSION_ID:
        return n + put_u8_attr(&buf[n], ZCL_TYPE_UINT8, ZIGBEE_APP_VERSION);
    case EZB_ZCL_ATTR_BASIC_STACK_VERSION_ID:
        return n + put_u8_attr(&buf[n], ZCL_TYPE_UINT8, ZIGBEE_STACK_VERSION);
    case EZB_ZCL_ATTR_BASIC_HW_VERSION_ID:
        return n + put_u8_attr(&buf[n], ZCL_TYPE_UINT8, ZIGBEE_HW_VERSION);
    case EZB_ZCL_ATTR_BASIC_MANUFACTURER_NAME_ID:
        return n + put_string_attr(&buf[n], ZIGBEE_MANUFACTURER_NAME);
    case EZB_ZCL_ATTR_BASIC_MODEL_IDENTIFIER_ID:
        return n + put_string_attr(&buf[n], ZIGBEE_MODEL_IDENTIFIER);
    case EZB_ZCL_ATTR_BASIC_DATE_CODE_ID:
        return n + put_string_attr(&buf[n], ZIGBEE_DATE_CODE);
    case EZB_ZCL_ATTR_BASIC_POWER_SOURCE_ID:
        return n + put_u8_attr(&buf[n], ZCL_TYPE_ENUM8,
                               EZB_ZCL_BASIC_POWER_SOURCE_SINGLE_PHASE_MAINS);
    case EZB_ZCL_ATTR_BASIC_SW_BUILD_ID_ID:
        return n + put_string_attr(&buf[n], ZIGBEE_SW_BUILD_ID);
    default:
        buf[n++] = ZCL_STATUS_UNSUPPORTED_ATTRIBUTE;
        return n;
    }
}

static void zcl_reply_basic_read(const ezb_zcl_cmd_hdr_t *hdr,
                                 const uint8_t *attr_ids,
                                 uint16_t attr_ids_len)
{
    static uint8_t rsp[128];
    uint16_t n = 0;

    rsp[n++] = ZCL_FC_SERVER_TO_CLIENT_NO_DEF_RSP;
    rsp[n++] = hdr->tsn;
    rsp[n++] = ZCL_CMD_READ_ATTRIBUTES_RSP;

    for (uint16_t i = 0; i + 1 < attr_ids_len; i += 2) {
        if (n + ZCL_MAX_ATTR_RECORD_LEN > sizeof(rsp)) {
            break;
        }
        n += put_basic_attr_record(&rsp[n], get_u16(&attr_ids[i]));
    }

    aps_send(short_addr_of(&hdr->src_addr, COORDINATOR_SHORT_ADDR),
             hdr->profile_id,
             EZB_ZCL_CLUSTER_ID_BASIC,
             hdr->dst_ep,
             hdr->src_ep,
             rsp,
             n);
}

/*
 * On/Off frames: any command from the coordinator other than a Default
 * Response means it configured or used the device. A StartUpOnOff write is
 * stored for the next boot; the stack still processes the write itself.
 */
static void handle_on_off_frame(const ezb_zcl_raw_frame_t *frame, bool cluster_specific)
{
    const ezb_zcl_cmd_hdr_t *hdr = frame->header;

    if (short_addr_of(&hdr->src_addr, INVALID_SHORT_ADDR) == COORDINATOR_SHORT_ADDR &&
        (cluster_specific || hdr->cmd_id != ZCL_CMD_DEFAULT_RSP)) {
        network_on_coordinator_configured();
    }

    /* Write Attributes record: AttrID(2) Type(1) Value(1) */
    if (!cluster_specific &&
        hdr->cmd_id == ZCL_CMD_WRITE_ATTRIBUTES &&
        frame->payload != NULL &&
        frame->payload_length >= 4 &&
        get_u16(frame->payload) == EZB_ZCL_ATTR_ON_OFF_START_UP_ON_OFF_ID) {
        relay_set_startup_on_off(frame->payload[3]);
    }
}

/* -------------------------------------------------------------------------- */
/* Stack handlers                                                             */
/* -------------------------------------------------------------------------- */

static bool aps_indication_handler(const ezb_apsde_data_ind_t *ind)
{
    uint16_t src = short_addr_of(&ind->src_address, INVALID_SHORT_ADDR);

    if (ind->profile_id != ZDO_PROFILE_ID || src == INVALID_SHORT_ADDR) {
        return false;
    }

    return handle_zdo_request(ind, src);
}

static void aps_confirm_handler(const ezb_apsde_data_confirm_t *confirm)
{
    if (confirm->status != 0) {
        ESP_LOGW(TAG, "Delivery failed: profile 0x%04x cluster 0x%04x status 0x%02x",
                 confirm->profile_id, confirm->cluster_id, confirm->status);
        return;
    }

    /* Simple Descriptor delivered: the coordinator finished the ZDO interview */
    if (confirm->profile_id == ZDO_PROFILE_ID &&
        confirm->cluster_id == (ZDO_SIMPLE_DESC_REQ | ZDO_RESPONSE_FLAG)) {
        network_on_interview_complete();
    }
}

static bool zcl_raw_handler(const ezb_zcl_raw_frame_t *frame)
{
    const ezb_zcl_cmd_hdr_t *hdr = frame->header;

    if (hdr == NULL) {
        return false;
    }

    bool cluster_specific = (hdr->fc & ZCL_FRAME_TYPE_MASK) == ZCL_FRAME_TYPE_CLUSTER_SPECIFIC;

    if (hdr->cluster_id == EZB_ZCL_CLUSTER_ID_ON_OFF) {
        handle_on_off_frame(frame, cluster_specific);
        return false; /* the stack handles the On/Off cluster */
    }

    if (hdr->cluster_id == EZB_ZCL_CLUSTER_ID_BASIC &&
        !cluster_specific &&
        hdr->cmd_id == ZCL_CMD_READ_ATTRIBUTES &&
        frame->payload != NULL) {
        zcl_reply_basic_read(hdr, frame->payload, frame->payload_length);
        return true;
    }

    return false;
}

void zb_responses_register(void)
{
    ezb_zcl_raw_command_handler_register(zcl_raw_handler);
    ezb_apsde_data_indication_handler_register(aps_indication_handler);
    ezb_apsde_data_confirm_handler_register(aps_confirm_handler);
}
